test_diff_full:
diff --git a/tests/test_elastigroup.py b/tests/test_elastigroup.py
index 78725db..0923f5b 100644
--- a/tests/test_elastigroup.py
+++ b/tests/test_elastigroup.py
@@ -664,21 +664,43 @@ def test_public_ips():


 def test_extract_image_id():
+    # Test backward compatibility - function can be called with one parameter
+    config_backward_compat = {}
+    extract_image_id(config_backward_compat)
+    expected_backward = {"Fn::FindInMap": ["Images", {"Ref": "AWS::Region"}, "LatestTaupageImage"]}
+    assert config_backward_compat["compute"]["launchSpecification"]["imageId"] == expected_backward
+
     test_cases = [
         {  # default behavior - set latest taupage image
             "given_config": {},
+            "original_config": {},
             "expected_config": {"compute": {"launchSpecification": {
                 "imageId": {"Fn::FindInMap": ["Images", {"Ref": "AWS::Region"}, "LatestTaupageImage"]}
             }}},
         },
         {  # leave imageId untouched
             "given_config": {"compute": {"launchSpecification": {"imageId": "fake-id"}}},
+            "original_config": {},
             "expected_config": {"compute": {"launchSpecification": {"imageId": "fake-id"}}},
         },
+        {  # use custom image from configuration
+            "given_config": {},
+            "original_config": {"Image": "LatestTaupageStagingImage"},
+            "expected_config": {"compute": {"launchSpecification": {
+                "imageId": {"Fn::FindInMap": ["Images", {"Ref": "AWS::Region"}, "LatestTaupageStagingImage"]}
+            }}},
+        },
+        {  # use another custom image from configuration
+            "given_config": {},
+            "original_config": {"Image": "LatestTaupageDevImage"},
+            "expected_config": {"compute": {"launchSpecification": {
+                "imageId": {"Fn::FindInMap": ["Images", {"Ref": "AWS::Region"}, "LatestTaupageDevImage"]}
+            }}},
+        },
     ]
     for test_case in test_cases:
         got = test_case["given_config"]
-        extract_image_id(got)
+        extract_image_id(got, test_case["original_config"])
         assert test_case["expected_config"] == got
